import{describe,it,expect}from"vitest";import{BUDDHISM_ERAS_DATA,getCumulativeRoutes,renderEraDetails}from"../../frontend/buddhism-spread-map/script.js";describe("Buddhism Spread Map Logic",()=>{it("should contain 5 chronological eras with objective historical data",()=>{expect(Array.isArray(BUDDHISM_ERAS_DATA)).toBe(!0),expect(BUDDHISM_ERAS_DATA.length).toBe(5),BUDDHISM_ERAS_DATA.forEach(e=>{expect(e).toHaveProperty("id"),expect(e).toHaveProperty("title"),expect(e).toHaveProperty("timeframe"),expect(e).toHaveProperty("summary"),expect(Array.isArray(e.routes)).toBe(!0),expect(Array.isArray(e.highlights)).toBe(!0)})}),it("should accumulate route vectors progressively per era step",()=>{const e=getCumulativeRoutes(0),t=getCumulativeRoutes(1),r=getCumulativeRoutes(3);expect(e.length).toBe(0),expect(t.length).toBe(2),expect(r.length).toBe(7)}),it("should render detailed HTML card for selected era",()=>{const e=renderEraDetails(0);expect(e).toContain("Origins in Ancient Magadha & Ganges Basin"),expect(e).toContain("Bodh Gaya & Sarnath");const t=renderEraDetails(1);expect(t).toContain("Mauryan Expansion under Emperor Ashoka"),expect(t).toContain("3rd Century BCE");const r=renderEraDetails(3);expect(r).toContain("Silk Road & Transmission to East Asia"),expect(r).toContain("Scholar-Translators")})});